INSERT INTO products (id, merchant_id, category_id, category_path, title, subtitle, main_image, detail_html, brand, status, created_at, updated_at) VALUES
  ('01J9Z8K2M4N5P6Q7R8S9T0V1W2', '01J9Z8K2M4N5P6Q7R8S9T0V1M1', '01J9Z8K2M4N5P6Q7R8S9T0V1C3', '["数码","耳机","真无线耳机"]', '极光 Pro 真无线降噪耳机', '45dB 深度降噪 · 综合续航 36 小时', 'data:image/png;base64,', '<h2>极光 Pro 真无线降噪耳机</h2><p>45dB 深度混合主动降噪，单次续航 8 小时，配充电仓综合续航 36 小时。</p><p><strong>重要提示：耳机本体防护等级为 IPX5（仅防日常出汗与轻度小雨泼溅），充电仓本体不具备防水能力（IPX0）。禁止佩戴游泳、潜水、泡温泉、淋浴或用水龙头直接冲洗；进液属人为损坏，不在保修范围。</strong></p>', '极光', 'onsale', '2026-06-01T02:00:00.000Z', '2026-09-18T03:00:00.000Z'),
  ('01J9Z8K2M4N5P6Q7R8S9T0V1X1', '01J9Z8K2M4N5P6Q7R8S9T0V1M1', '01J9Z8K2M4N5P6Q7R8S9T0V1C5', '["数码","音箱","便携音箱"]', '极光 Lite 便携户外蓝牙音箱', 'IP67 防尘防水 · 续航 15 小时', 'data:image/png;base64,', '<h2>极光 Lite 便携户外蓝牙音箱</h2><p>双 10W 全频扬声器 + 双被动低音辐射板，4000mAh 电池连续播放约 15 小时。</p><p><strong>整机 IP67 防尘防水，支持 1 米深清水短时浸泡 30 分钟；但不可在海水、热水、温泉或化学液体中使用。</strong></p>', '极光', 'onsale', '2026-07-10T02:00:00.000Z', '2026-09-19T02:00:00.000Z')
